// Deduplicate by code
const seen = new Set();
const unique = [];
for (const c of INDIAN_COLLEGES) {
  if (!seen.has(c.code)) {
    seen.add(c.code);
    unique.push(c);
  }
}

export async function seedCollegeDirectory() {
  const dir = col('college-directory');
  if (await dir.countDocuments() > 0) return;
  
  const docs = unique.map(c => ({
    _id: `dir-${c.code}`,
    ...c,
    createdAt: new Date().toISOString(),
  }));
  
  // Insert in batches of 50
  for (let i = 0; i < docs.length; i += 50) {
    await dir.insertMany(docs.slice(i, i + 50));
  }
  console.log(`  ✓ Seeded ${docs.length} colleges in directory`);
}
